def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    dxs = [0,1,0,-1]
    dys = [1,0,-1,0]
    obstacles = set(observation.get('obstacles',[]))
    resources = observation.get('resources',[])
    opponent_x, opponent_y = observation.get('opponent_position', (0,0))
    score = observation.get('scores', [0,0])
    opponent_score = score[1]
    my_score = score[0]
    def safe(nx, ny):
        return 0<=nx<width and 0<=ny<height and (nx,ny) not in obstacles
    # Prioritize adjacent resources
    for res in resources:
        rx, ry = res
        if abs(rx - x) + abs(ry - y) == 1:
            return [rx - x, ry - y]
    # Chase opponent if leading
    if my_score >= opponent_score:
        for dir in range(4):
            nx, ny = x + dxs[dir], y + dys[dir]
            if safe(nx, ny):
                if abs(opponent_x - nx) + abs(opponent_y - ny) < abs(opponent_x - x) + abs(opponent_y - y):
                    return [dxs[dir], dys[dir]]
    # Otherwise, move towards resources
    min_dist = float('inf')
    target = None
    for res in resources:
        dist = abs(res[0]-x)+abs(res[1]-y)
        if dist < min_dist:
            min_dist = dist
            target = res
    if target:
        tx, ty = target
        dx, dy = 0,0
        if tx > x: dx = 1
        elif tx < x: dx = -1
        if ty > y: dy = 1
        elif ty < y: dy = -1
        if safe(x+dx, y+dy):
            return [dx, dy]
        if safe(x+dx, y):
            return [dx, 0]
        if safe(x, y+dy):
            return [0, dy]
    # Move randomly if no other option
    for dir in range(4):
        nx, ny = x + dxs[dir], y + dys[dir]
        if safe(nx, ny):
            return [dxs[dir], dys[dir]]
    return [0,0]
